void setUp(void) {}
void tearDown(void) {}

void test_total_adds(void) {
  TEST_ASSERT_EQUAL_INT(3, total(1, 2));
  TEST_ASSERT_EQUAL_INT(0, total(0, 0));
}

void test_discount_lowers_the_price(void) {
  TEST_ASSERT_EQUAL_INT(90, discount(100, 10));
}

int main(void) {
  UNITY_BEGIN();
  RUN_TEST(test_total_adds);
  RUN_TEST(test_discount_lowers_the_price);
  return UNITY_END();
}

