package pricing

import "testing"

func TestTotal(t *testing.T) {
	tests := []struct {
		name string
		a, b int
		want int
	}{
		{name: "small", a: 1, b: 2, want: 3},
		{name: "equal", a: 2, b: 2, want: 4},
		{name: "large", a: 50, b: 60, want: 110},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := Total(tc.a, tc.b); got != tc.want {
				t.Errorf("Total(%d, %d) = %d, want %d", tc.a, tc.b, got, tc.want)
			}
		})
	}
}

